WITH base AS (SELECT id, product_name, category, brand, price, cost, stock_qty, launch_date, tags, supplier_id, ROUND(stock_qty / price, 2) AS stock_qty_per_price, CASE WHEN price >= 980 THEN 'High' WHEN price >= 260 THEN 'Medium' ELSE 'Low' END AS price_band FROM products WHERE brand IS NOT NULL AND brand NOT IN ('Stark', 'Initech')), joined AS (SELECT src.*, d.city FROM base src LEFT JOIN suppliers d ON src.supplier_id = d.id), filtered AS (SELECT id, product_name, brand, price, cost, stock_qty, launch_date, tags, supplier_id, stock_qty_per_price, price_band, ARRAY_CONTAINS(tags, 'premium') AS is_premium, cost + stock_qty_per_price AS cost_plus_stock_qty_per_price, COALESCE(brand, 'UNKNOWN') AS brand_filled FROM joined WHERE ARRAY_CONTAINS(tags, 'sale')), with_windows AS (SELECT *, SUM(cost_plus_stock_qty_per_price) OVER (PARTITION BY brand, supplier_id ORDER BY cost_plus_stock_qty_per_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_cost_plus_stock_qty_per_price, AVG(cost_plus_stock_qty_per_price) OVER (PARTITION BY brand, supplier_id ORDER BY cost_plus_stock_qty_per_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_cost_plus_stock_qty_per_price, MIN(cost_plus_stock_qty_per_price) OVER (PARTITION BY brand, supplier_id ORDER BY cost_plus_stock_qty_per_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_cost_plus_stock_qty_per_price FROM filtered WHERE stock_qty BETWEEN 189 AND 340) SELECT s.id, s.brand, s.cost, s.stock_qty, s.launch_date, s.supplier_id, s.stock_qty_per_price, s.price_band, s.is_premium, (SELECT SUM(x.cost) FROM products x WHERE x.supplier_id = s.supplier_id) AS sum_product_cost FROM with_windows s
